CREATE TYPE public.app_role AS ENUM ('admin', 'editor', 'assistant');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, notification_preferences jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_self ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_update_self ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_self ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE FUNCTION public.is_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid()) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role), public.is_staff() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role), public.is_staff() TO authenticated;
CREATE FUNCTION public.create_staff_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (NEW.id, coalesce(NEW.raw_user_meta_data->>'full_name', '')); RETURN NEW; END $$;
CREATE TRIGGER create_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_staff_profile();
INSERT INTO public.profiles(id, display_name) SELECT id, coalesce(raw_user_meta_data->>'full_name', '') FROM auth.users ON CONFLICT(id) DO NOTHING;
ALTER TABLE public.enquiries ADD COLUMN staff_notes text NOT NULL DEFAULT '', ADD COLUMN assigned_to uuid;
ALTER TABLE public.consultation_bookings ADD COLUMN staff_notes text NOT NULL DEFAULT '', ADD COLUMN assigned_to uuid;
GRANT SELECT ON public.enquiries, public.consultation_bookings TO authenticated;
GRANT UPDATE(status, staff_notes, assigned_to) ON public.enquiries, public.consultation_bookings TO authenticated;
GRANT ALL ON public.enquiries, public.consultation_bookings TO service_role;
ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.consultation_bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY enquiries_staff_read ON public.enquiries FOR SELECT TO authenticated USING (public.is_staff());
CREATE POLICY enquiries_staff_update ON public.enquiries FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'assistant')) WITH CHECK (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'assistant'));
CREATE POLICY bookings_staff_read ON public.consultation_bookings FOR SELECT TO authenticated USING (public.is_staff());
CREATE POLICY bookings_staff_update ON public.consultation_bookings FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'assistant')) WITH CHECK (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'assistant'));
CREATE TABLE public.staff_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, record_id uuid NOT NULL, record_type text NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.staff_activity TO authenticated;
GRANT ALL ON public.staff_activity TO service_role;
ALTER TABLE public.staff_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_admin_read ON public.staff_activity FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE FUNCTION public.log_staff_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NOT NULL AND ROW(OLD.status, OLD.staff_notes, OLD.assigned_to) IS DISTINCT FROM ROW(NEW.status, NEW.staff_notes, NEW.assigned_to) THEN INSERT INTO public.staff_activity(actor_id, record_id, record_type, action) VALUES(auth.uid(), NEW.id, TG_TABLE_NAME, CASE WHEN OLD.status IS DISTINCT FROM NEW.status THEN 'Status: ' || OLD.status || ' → ' || NEW.status ELSE 'Notes or assignment updated' END); END IF; RETURN NEW; END $$;
CREATE TRIGGER log_enquiry_update AFTER UPDATE ON public.enquiries FOR EACH ROW EXECUTE FUNCTION public.log_staff_update();
CREATE TRIGGER log_booking_update AFTER UPDATE ON public.consultation_bookings FOR EACH ROW EXECUTE FUNCTION public.log_staff_update();
CREATE FUNCTION public.validate_staff_status() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF TG_TABLE_NAME = 'enquiries' AND NEW.status NOT IN ('new','contacted','converted','closed') THEN RAISE EXCEPTION 'Invalid enquiry status'; END IF; IF TG_TABLE_NAME = 'consultation_bookings' AND NEW.status NOT IN ('pending','confirmed','cancelled','completed') THEN RAISE EXCEPTION 'Invalid booking status'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_enquiry_status BEFORE INSERT OR UPDATE ON public.enquiries FOR EACH ROW EXECUTE FUNCTION public.validate_staff_status();
CREATE TRIGGER validate_booking_status BEFORE INSERT OR UPDATE ON public.consultation_bookings FOR EACH ROW EXECUTE FUNCTION public.validate_staff_status();